<?php declare(strict_types=1);require_once __DIR__.'/../auth/seguridad.php';require_once __DIR__.'/../conexion_postgres.php';exigirAdministrador(['POST']);$d=json_decode(file_get_contents('php://input'),true);$n=trim((string)($d['name']??''));$e=strtolower(trim((string)($d['email']??'')));$p=(string)($d['password']??'');$r=$d['role']??'user';if($n===''||!filter_var($e,FILTER_VALIDATE_EMAIL)||strlen($p)<8||!in_array($r,['user','admin'],true))responderJson(['error'=>'Datos no válidos.'],400);try{$q=retornarConexionPostgres()->prepare('insert into public.users(name,email,password,role) values(:n,:e,:p,:r) returning id,name,email,role');$q->execute([':n'=>$n,':e'=>$e,':p'=>password_hash($p,PASSWORD_DEFAULT),':r'=>$r]);responderJson(['result'=>'OK','message'=>'Usuario creado.','user'=>$q->fetch()],201);}catch(PDOException $x){responderJson(['error'=>$x->getCode()==='23505'?'El email ya está registrado.':'No se pudo crear el usuario.'],$x->getCode()==='23505'?409:500);}
